      "mainEntity": [
        {
          "@type": "Question",
          "name": "What areas in Kern County do you serve?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS provides scheduled commercial electronics recycling pickups throughout Bakersfield, Oildale, Rosedale, Greenacres, Delano, Shafter, Wasco, Arvin, and surrounding agricultural and logistics corridors across Kern County."
          }
        },
        {
          "@type": "Question",
          "name": "Is data destruction HIPAA compliant for Bakersfield healthcare providers?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. STS provides HIPAA-compliant data destruction for healthcare networks such as Kern Medical and Adventist Health Bakersfield, providing Business Associate Agreements and serialized Certificates of Destruction that satisfy OCR compliance audits."
          }
        },
        {
          "@type": "Question",
          "name": "Is commercial electronics pickup free in Bakersfield?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS offers complimentary on-site pickup for qualifying volumes of enterprise IT hardware, servers, workstations, and networking systems for businesses, school districts, and municipal offices across Bakersfield."
          }
        },
        {
          "@type": "Question",
          "name": "What standards govern your data destruction process?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Our data sanitization and physical destruction procedures align with NIST SP 800-88 Rev. 2 and DoD guidelines, ensuring that digital storage media from Kern County facilities is rendered completely unrecoverable."
          }
        },
        {
          "@type": "Question",
          "name": "How quickly can an enterprise pickup be scheduled in Bakersfield?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Most commercial electronics pickups across Bakersfield and Kern County are scheduled within the same week of request, coordinating dock times that prevent business interruption."
          }
        },
        {
          "@type": "Question",
          "name": "Do you provide ITAD services for agribusiness and energy corporations?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS manages enterprise IT asset disposition for major Central Valley operators like California Resources Corporation and Grimmway Farms, providing serialized inventorying, remarketing assessments, and compliant e-waste handling."
          }
        },
        {
          "@type": "Question",
          "name": "Where is equipment processed after collection in Bakersfield?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Equipment gathered in Bakersfield is safely staged and transported to one of our certified processing facilities in Jacksonville, Texas and Houston, Texas, where comprehensive data destruction and zero-landfill material recovery occur."
          }
        },
        {
          "@type": "Question",
          "name": "Can Bakersfield companies recover value from retired IT assets?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes, our IT asset recovery and remarketing programs evaluate functional laptops, servers, and enterprise hardware, providing financial return to offset technology refresh costs for Kern County organizations."
          }
        }
      ]
